package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolCuts;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: what each person has claimed, their due-total and
 * overdue-total, and the sheet's claimed-total, due-total and overdue-total. A change takes them
 * before it writes and has them audited after its own records, so every figure it moves is recorded.
 */
@Service
public class Rollups {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /**
     * A person's figures: what they have claimed, their due-total (null when n/a) and their
     * overdue-total (the due of their counting overdue claims), with their settled-total (the due of
     * their counting SETTLED claims that correct nothing) and how many of their counting claims are overdue, which make their score.
     */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal,
            BigDecimal settledTotal, int overdueCount) {

        /**
         * Their score as the screen shows it: their settled-total over 100, less 5 for each overdue
         * claim, rounded half to even to a whole number.
         */
        public long score() {
            return settledTotal.subtract(BigDecimal.valueOf(500L * overdueCount))
                    .divide(BigDecimal.valueOf(100), 0, RoundingMode.HALF_EVEN).longValueExact();
        }

        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal)
                    && same(overdueTotal, other.overdueTotal);
        }
    }

    /**
     * The sheet's figures: each person's by id, in list order, the sheet's totals, and how many of its
     * counting claims are overdue.
     */
    public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal, int overdueCount) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final SheetRepository sheets;
    private final Dues dues;
    private final Audit audit;
    private final PoolCuts cuts;

    public Rollups(PersonRepository people, ClaimRepository claims, SheetRepository sheets,
            Dues dues, Audit audit, PoolCuts cuts) {
        this.cuts = cuts;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.dues = dues;
        this.audit = audit;
    }

    /** The sheet's figures as they stand now in the current transaction. */
    public Rollup take(String sheetId) {
        Map<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        return take(sheet, dues.live(sheetId), sheetPeople, claims.findBySheetIdOrderByIdDesc(sheetId),
                cuts.personCuts(sheet, sheetPeople.values()));
    }

    /**
     * The sheet's figures over its records as they stand now, read as if its today were a preview day
     * (null: its own today), held in no store.
     */
    public Rollup take(String sheetId, LocalDate preview) {
        Sheet now = sheets.findById(sheetId).orElse(null);
        if (preview == null || now == null) {
            return take(sheetId);
        }
        Sheet then = now.asOf(preview, now.getDated(), now.getPolicyDate());
        Map<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        return take(then, previewBasis(then), sheetPeople, claims.findBySheetIdOrderByIdDesc(sheetId),
                cuts.personCuts(then, sheetPeople.values()));
    }

    /** The basis a sheet held in no store, with a preview day as its today, reads its dues against: its live one. */
    public Dues.Basis previewBasis(Sheet then) {
        Dues.Basis live = dues.live(then.getId());
        return new Dues.Basis(then, live.rates(), live.inherited(), live.corrected());
    }

    /**
     * A sheet's figures read from what is given, as {@link #take(Sheet, Dues.Basis, Map, Iterable, Map)}
     * with no one's cuts.
     */
    public Rollup take(Sheet sheet, Dues.Basis basis, Map<Long, Person> sheetPeople, Iterable<Claim> sheetClaims) {
        return take(sheet, basis, sheetPeople, sheetClaims, Map.of());
    }

    /**
     * A sheet's figures read from what is given, held in no store or not: the sheet (null when not found;
     * its today is the day they are read on), the basis their dues are read against, its people by id in
     * list order, its claims, and each person's cut total by id (none: no cut), which the cap covers too.
     */
    public Rollup take(Sheet sheet, Dues.Basis basis, Map<Long, Person> sheetPeople, Iterable<Claim> sheetClaims,
            Map<Long, BigDecimal> personCuts) {
        LocalDate today = sheet == null ? null : sheet.getToday();
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : sheetClaims) {
            if (claim.getStatus().counts()) {
                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        // The parts of shared claims their holders' due-totals count, by holder, from the claims that
        // count for their own person; each claim's figure as read here.
        // A holder whose grade has no rate has a part of 0.00, which gives them no figure.
        Map<Claim, BigDecimal> shared = new java.util.IdentityHashMap<>();
        Map<Long, BigDecimal> received = new LinkedHashMap<>();
        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
            Person person = entry.getValue();
            for (Claim claim : byPerson.getOrDefault(entry.getKey(), List.of())) {
                if (claim.getShares().isEmpty()
                        || !person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)) {
                    continue;
                }
                BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()), basis);
                if (figure == null) {
                    continue;
                }
                shared.put(claim, claim.sharedParts(share -> {
                    Person holder = sheetPeople.get(share.getPersonId());
                    BigDecimal part = dues.part(claim, share,
                            holder == null ? null : holder.gradeOn(claim.getDate()), figure, basis);
                    if (part != null) {
                        received.merge(share.getPersonId(), part, BigDecimal::add);
                    }
                    return part;
                }));
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        int overdueCount = 0;
        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
            Person person = entry.getValue();
            List<Claim> personClaims = byPerson.getOrDefault(entry.getKey(), List.of());
            BigDecimal claimed = zero();
            for (Claim claim : personClaims) {
                // What is claimed leaves out claims that correct another.
                if (person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)
                        && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
                    claimed = claimed.add(claim.getAmount());
                }
            }
            List<Claim> counting = personClaims.stream()
                    .filter(claim -> person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today))
                    .toList();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            BigDecimal settled = zero();
            int personOverdue = 0;
            boolean figured = false;
            for (Claim claim : counting) {
                String grade = person.gradeOn(claim.getDate());
                boolean late = overdue(claim, sheet, grade);
                if (late) {
                    overdueCount++;
                    personOverdue++;
                }
                BigDecimal figure = dues.due(claim, grade, basis);
                if (figure != null) {
                    // A shared claim's own person counts its figure less its holders' parts.
                    due = due.add(shared.containsKey(claim) ? figure.subtract(shared.get(claim)) : figure);
                    figured = true;
                    if (late) {
                        overdue = overdue.add(figure);
                    }
                    // The score's settled figures leave out claims that correct another.
                    if (claim.getStatus() == ClaimStatus.SETTLED
                            && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
                        settled = settled.add(figure);
                    }
                }
            }
            BigDecimal part = received.get(entry.getKey());
            if (part != null) {
                due = due.add(part);
                figured = true;
            }
            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
            // figure (a fixed one, or one at the grade in force on its own date).
            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
            if (!rated && !figured) {
                due = null;
            }
            // A due-total is at most the sheet's cap less their cut total, not below 0.00.
            if (sheet != null) {
                due = sheet.capped(due, personCuts.getOrDefault(entry.getKey(), zero()));
            }
            figures.put(entry.getKey(), new Figures(person.getName(), claimed, due, overdue, settled, personOverdue));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) {
                dueFigures.add(due);
            }
            overdueFigures.add(overdue);
        }
        return new Rollup(figures, claimedTotal, trimmed(dueFigures), trimmed(overdueFigures), overdueCount);
    }

    /**
     * The sum of the people's figures, leaving out the single highest and the single lowest when there
     * are three or more.
     */
    static BigDecimal trimmed(List<BigDecimal> figures) {
        BigDecimal total = zero();
        for (BigDecimal figure : figures) {
            total = total.add(figure);
        }
        if (figures.size() >= 3) {
            BigDecimal highest = figures.stream().max(BigDecimal::compareTo).orElseThrow();
            BigDecimal lowest = figures.stream().min(BigDecimal::compareTo).orElseThrow();
            total = total.subtract(highest).subtract(lowest);
        }
        return total;
    }

    /**
     * Record, once the change commits, one ROLLUP line per person whose figures moved since
     * {@code before} (a person new since then counts as moved), then a TOTALS line when any of the sheet's
     * totals moved, then one ALERT line per person, in list order, whose due-total went from at or below
     * the sheet's alert threshold (or none) to above it.
     */
    public void audit(String sheetId, String user, Rollup before) {
        Rollup after = take(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordFiguresOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + shown(figures.dueTotal())
                        + " overdue-total=" + figures.overdueTotal().toPlainString());
            }
        });
        if (!same(after.claimedTotal(), before.claimedTotal()) || !same(after.dueTotal(), before.dueTotal())
                || !same(after.overdueTotal(), before.overdueTotal())) {
            audit.recordFiguresOnCommit("TOTALS sheet=" + sheetId + " by=" + user
                    + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString()
                    + " overdue-total=" + after.overdueTotal().toPlainString());
        }
        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
        if (threshold != null) {
            after.people().forEach((id, figures) -> {
                Figures was = before.people().get(id);
                if (above(figures.dueTotal(), threshold) && !(was != null && above(was.dueTotal(), threshold))) {
                    audit.recordFiguresOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
                            + " due-total=" + figures.dueTotal().toPlainString());
                }
            });
        }
    }

    /** Whether a due-total is above a threshold; n/a never is. */
    private static boolean above(BigDecimal due, BigDecimal threshold) {
        return due != null && due.compareTo(threshold) > 0;
    }

    /**
     * Whether a claim is overdue: OPEN or PENDING with its due-by (plus its grade's grace, see
     * {@link Sheet#lateFrom}) before the sheet's today, and not deferred on it.
     */
    private static boolean overdue(Claim claim, Sheet sheet, String grade) {
        if (sheet == null) {
            return false;
        }
        LocalDate today = sheet.getToday();
        return claim.getStatus().isOpen() && sheet.lateFrom(claim.getDueBy(), grade, claim.getDate()).isBefore(today)
                && !claim.isDeferredOn(today);
    }

    /** Whether two figures are the same amount, or both n/a. */
    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    /** A due-total as shown: two decimals, or n/a. */
    public static String shown(BigDecimal due) {
        return due != null ? due.toPlainString() : NO_RATE;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolCuts;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures of a sheet consolidated over it and all its descendants (the sheets naming it as their
 * parent, theirs, and so on), each sheet's as that sheet shows them now, or as it stood at the end of an
 * as-of date.
 */
@Service
public class Consolidation {

    /**
     * The number of people (those whose names or aliases match counted once), the people's due-totals and
     * overdue-totals over the whole tree added up, leaving out the single highest and single lowest when
     * there are three or more, per grade the due-totals of the
     * people not retired who have it in force on their sheet's today (those shown as n/a skipped) added
     * up, and per status how many claims have it.
     */
    public record Consolidated(int peopleCount, BigDecimal dueTotal, BigDecimal overdueTotal,
            Map<String, BigDecimal> gradeDueTotals, Map<String, Integer> statusCounts) {
    }

    /** A sheet's figures with the people and claims they were read from. */
    private record Taken(Sheet sheet, Rollups.Rollup rollup, Map<Long, Person> people, Iterable<Claim> claims) {
    }

    private final SheetRepository sheets;
    private final Rollups rollups;
    private final SheetHistory history;
    private final Dues dues;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final PoolCuts cuts;

    public Consolidation(SheetRepository sheets, Rollups rollups, SheetHistory history, Dues dues,
            PersonRepository people, ClaimRepository claims, PoolCuts cuts) {
        this.cuts = cuts;
        this.sheets = sheets;
        this.rollups = rollups;
        this.history = history;
        this.dues = dues;
        this.people = people;
        this.claims = claims;
    }

    /** The sheet's figures added to those of all its descendants, each as it stands now. */
    @Transactional(readOnly = true)
    public Consolidated of(String sheetId) {
        return of(sheetId, null);
    }

    /**
     * The sheet's figures added to those of all its descendants (the tree as it is set now), each sheet's
     * as it stood at the end of an as-of date (null: as it stands now), with that date as its today.
     */
    @Transactional(readOnly = true)
    public Consolidated of(String sheetId, LocalDate asOf) {
        return of(sheetId, asOf, null);
    }

    /**
     * As {@link #of(String, LocalDate)}; with no as-of date but a preview day, each sheet's figures over its
     * records as they stand now, read as if its today were that day.
     */
    @Transactional(readOnly = true)
    public Consolidated of(String sheetId, LocalDate asOf, LocalDate preview) {
        List<String> all = new ArrayList<>();
        all.add(sheetId);
        all.addAll(sheets.descendants(sheetId));
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        List<Set<String>> persons = new ArrayList<>();
        Map<String, BigDecimal> grades = new TreeMap<>();
        Map<String, Integer> statuses = new TreeMap<>();
        for (String id : all) {
            Taken taken = asOf != null ? asOf(id, asOf) : preview != null ? preview(id, preview) : now(id);
            Rollups.Rollup rollup = taken.rollup();
            rollup.people().values().forEach(figures -> {
                if (figures.dueTotal() != null) {
                    dueFigures.add(figures.dueTotal());
                }
                overdueFigures.add(figures.overdueTotal());
            });
            rollup.people().keySet().forEach(personId -> {
                Person person = taken.people().get(personId);
                if (person != null) {
                    persons.add(keys(person));
                }
            });
            addGradeDueTotals(taken, grades);
            for (Claim claim : taken.claims()) {
                statuses.merge(claim.getStatus().name(), 1, Integer::sum);
            }
        }
        return new Consolidated(distinct(persons), Rollups.trimmed(dueFigures), Rollups.trimmed(overdueFigures),
                grades, statuses);
    }

    /**
     * The sheet's own summary due-total per grade, as it stands now: the due-totals of the people not
     * retired who have it in force on its today (those shown as n/a skipped) added up; a grade nobody has
     * is left out. Empty when no sheet has the id.
     */
    @Transactional(readOnly = true)
    public Optional<Map<String, BigDecimal>> gradeDueTotals(String sheetId) {
        if (sheets.findById(sheetId).isEmpty()) {
            return Optional.empty();
        }
        Map<String, BigDecimal> grades = new TreeMap<>();
        addGradeDueTotals(now(sheetId), grades);
        return Optional.of(grades);
    }

    /** Add a sheet's people's due-totals to the per-grade totals (see {@link Consolidated}). */
    private static void addGradeDueTotals(Taken taken, Map<String, BigDecimal> grades) {
        LocalDate today = taken.sheet() == null ? null : taken.sheet().getToday();
        taken.people().forEach((personId, person) -> {
            Rollups.Figures figures = taken.rollup().people().get(personId);
            if (person.getRetiredFrom() != null || today == null || figures == null) {
                return;
            }
            BigDecimal figure = figures.dueTotal() == null ? BigDecimal.ZERO.setScale(2) : figures.dueTotal();
            grades.merge(person.gradeOn(today), figure, BigDecimal::add);
        });
    }

    /** A person's name and aliases, each as names are compared. */
    private static Set<String> keys(Person person) {
        Set<String> keys = new HashSet<>();
        keys.add(Person.keyOf(person.getName()));
        person.getAliases().forEach(alias -> keys.add(Person.keyOf(alias)));
        return keys;
    }

    /**
     * How many people there are when those whose names or aliases match, as names are compared, are one
     * person (and so on through whoever they match in turn).
     */
    private static int distinct(List<Set<String>> persons) {
        List<Set<String>> groups = new ArrayList<>();
        for (Set<String> person : persons) {
            Set<String> merged = new HashSet<>(person);
            for (Iterator<Set<String>> it = groups.iterator(); it.hasNext();) {
                Set<String> group = it.next();
                if (!Collections.disjoint(group, merged)) {
                    merged.addAll(group);
                    it.remove();
                }
            }
            groups.add(merged);
        }
        return groups.size();
    }

    /** A sheet's figures as it stands now. */
    private Taken now(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        return new Taken(sheet, rollups.take(sheet, dues.live(sheetId), sheetPeople, sheetClaims,
                cuts.personCuts(sheet, sheetPeople.values())), sheetPeople, sheetClaims);
    }

    /** A sheet's figures over its records as they stand now, read as if its today were a preview day. */
    private Taken preview(String sheetId, LocalDate day) {
        Sheet now = sheets.findById(sheetId).orElse(null);
        if (now == null) {
            return now(sheetId);
        }
        Sheet then = now.asOf(day, now.getDated(), now.getPolicyDate());
        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        return new Taken(then, rollups.take(then, rollups.previewBasis(then), sheetPeople, sheetClaims,
                cuts.personCuts(then, sheetPeople.values())), sheetPeople, sheetClaims);
    }

    /**
     * A sheet's figures as it stood at the end of a date, with that date as its today: before its today,
     * as kept for that date (none when nothing was kept by then); else as it stands.
     */
    private Taken asOf(String sheetId, LocalDate day) {
        Sheet now = sheets.findById(sheetId).orElse(null);
        if (now == null) {
            return now(sheetId);
        }
        if (day.isBefore(now.getToday())) {
            return history.at(sheetId, day)
                    .map(then -> new Taken(then.sheet(),
                            rollups.take(then.sheet(), then.basis(), then.people(), then.claims().values()),
                            then.people(), then.claims().values()))
                    .orElseGet(() -> {
                        Sheet empty = now.asOf(day, List.of(), null);
                        return new Taken(empty, rollups.take(empty, dues.live(sheetId), new LinkedHashMap<>(),
                                List.of()), Map.of(), List.of());
                    });
        }
        Sheet then = now.asOf(day, now.getDated(), now.getPolicyDate());
        Dues.Basis live = dues.live(sheetId);
        Dues.Basis basis = new Dues.Basis(then, live.rates(), history.inherited(sheetId, day), live.corrected());
        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        return new Taken(then, rollups.take(then, basis, sheetPeople, sheetClaims), sheetPeople, sheetClaims);
    }
}

