export class Consolidated {
  private readonly session = inject(Session);
  private readonly api = inject(ConsolidatedApi);
  private readonly gradeStore = inject(GradesStore);

  /** The sheet's own figures as shown: a move in any of them re-reads the consolidated ones. */
  readonly peopleCount = input.required<number>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();

  protected readonly figures = signal<ConsolidatedView | null>(null);
  /** Per grade, its consolidated due-total; empty until the figures are read. */
  protected readonly grades = computed(() => {
    const figures = this.figures();
    // The sheet's own grades, then any other grade one of its descendants has.
    const codes = [...this.gradeStore.codes()];
    for (const grade of Object.keys(figures?.gradeDueTotals ?? {})) {
      if (!codes.includes(grade)) codes.push(grade);
    }
    return codes.map((grade) => ({
      grade,
      dueTotal: figures ? (figures.gradeDueTotals[grade] ?? '0.00') : '',
    }));
  });
  /** Per status, its consolidated count of claims; empty until the figures are read. */
  protected readonly statuses = computed(() => {
    const figures = this.figures();
    return STATUSES.map((status) => ({
      status,
      count: figures ? String(figures.statusCounts[status] ?? 0) : '',
    }));
  });
  /** Counts reads, so only the answer to the latest one is shown. */
  private reads = 0;

  constructor() {
    // Every sheet load clears the figures shown and re-reads them.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.figures.set(null);
        if (sheet) void this.reload(sheet);
      });
    });
    // A move in the sheet's own today, its as-of date or its figures re-reads them.
    effect(() => {
      this.session.today();
      this.session.asOf();
      this.peopleCount();
      this.dueTotal();
      this.overdueTotal();
      untracked(() => {
        const sheet = this.session.sheet();
        if (sheet) void this.reload(sheet);
      });
    });
  }

  private async reload(sheet: string): Promise<void> {
    const read = ++this.reads;
    try {
      const figures = await this.api.get(sheet);
      if (read === this.reads && this.session.sheet() === sheet) this.figures.set(figures);
    } catch {
      // Left as it was: the next load or change reads them again.
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/**
 * A sheet's figures over it and all its descendants (the sheets naming it as their parent, theirs, and
 * so on), each sheet's as that sheet shows them now, or as it stood at the end of the as-of date while one
 * is set, with that date as its today.
 */
export interface ConsolidatedView {
  peopleCount: number;
  /** The sheets' due-totals added up, with two decimals. */
  dueTotal: string;
  /** The sheets' overdue-totals added up, with two decimals. */
  overdueTotal: string;
  /**
   * Per grade, the due-totals of the people not retired who have it in force on their sheet's today
   * added up, with two decimals; a grade nobody has is left out.
   */
  gradeDueTotals: Record<string, string>;
  /** Per status, how many claims have it; a status no claim has is left out. */
  statusCounts: Record<string, number>;
}

/** A sheet's own summary due-total per grade, with two decimals (a grade nobody has left out); not found when no sheet has the id. */
export interface GradeDueTotalsView {
  found: boolean;
  gradeDueTotals: Record<string, string>;
}

// The consolidated figures, read from the store.
@Injectable({ providedIn: 'root' })
export class ConsolidatedApi {
  private readonly http = inject(HttpClient);

  get(sheet: string): Promise<ConsolidatedView> {
    return firstValueFrom(this.http.get<ConsolidatedView>(`/api/sheets/${encodeURIComponent(sheet)}/consolidated`));
  }

  /** Another sheet's own summary due-totals per grade, as it stands now. */
  gradeDueTotals(sheet: string): Promise<GradeDueTotalsView> {
    return firstValueFrom(
      this.http.get<GradeDueTotalsView>(`/api/sheets/${encodeURIComponent(sheet)}/grade-due-totals`),
    );
  }
}
package net.officefloor.hq.app.rollup;

import jakarta.validation.constraints.NotBlank;
import java.util.LinkedHashMap;
import java.util.Map;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.PreviewDate;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class ConsolidationController {

    /**
     * What the screen is told about the consolidated figures: the due amounts with two decimals, per grade
     * found the due-totals, and per status found the count of claims.
     */
    public record ConsolidatedView(int peopleCount, String dueTotal, String overdueTotal,
            Map<String, String> gradeDueTotals, Map<String, Integer> statusCounts) {
    }

    /**
     * A sheet's own summary due-total per grade, with two decimals (a grade nobody has left out); not
     * found when no sheet has the id.
     */
    public record GradeDueTotalsView(boolean found, Map<String, String> gradeDueTotals) {
    }

    private final Consolidation consolidation;

    public ConsolidationController(Consolidation consolidation) {
        this.consolidation = consolidation;
    }

    /**
     * The sheet's figures over it and all its descendants, as each stands now, or while an as-of date is
     * set, as each stood at the end of that date, or while a preview date is set, as each stands now read
     * as if its today were that date.
     */
    @GetMapping("/{id}/consolidated")
    public ConsolidatedView consolidated(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf,
            @RequestHeader(value = PreviewDate.HEADER, required = false) String preview) {
        Consolidation.Consolidated figures = consolidation.of(id, AsOfGuard.date(asOf),
                PreviewDate.date(asOf, preview));
        Map<String, String> grades = new LinkedHashMap<>();
        figures.gradeDueTotals().forEach((grade, due) -> grades.put(grade, due.toPlainString()));
        return new ConsolidatedView(figures.peopleCount(), figures.dueTotal().toPlainString(),
                figures.overdueTotal().toPlainString(), grades, figures.statusCounts());
    }

    /** A sheet's own summary due-totals per grade as it stands now, to compare another sheet with it. */
    @GetMapping("/{id}/grade-due-totals")
    public GradeDueTotalsView gradeDueTotals(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String id) {
        return consolidation.gradeDueTotals(id)
                .map(totals -> {
                    Map<String, String> grades = new LinkedHashMap<>();
                    totals.forEach((grade, due) -> grades.put(grade, due.toPlainString()));
                    return new GradeDueTotalsView(true, grades);
                })
                .orElseGet(() -> new GradeDueTotalsView(false, Map.of()));
    }
}

